arguments.command:
cat > /tmp/mc/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo x-access-token ;;
  *Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/mc/askpass.sh && cd /home/runner/work/beetle-in-the-anthill/monica-conv && GIT_ASKPASS=/tmp/mc/askpass.sh GIT_TERMINAL_PROMPT=0 git -c credential.helper= push origin HEAD:refs/heads/friend/monica 2>&1 | tail -5
